{
  "name": "opencode-aifs-provider",
  "version": "0.5.0",
  "description": "OpenCode V2 plugin that auto-discovers AIFS LLM Serving models at runtime from the /models endpoint.",
  "license": "MIT",
  "author": "Sven Weber",
  "keywords": [
    "opencode",
    "aifs",
    "t-systems",
    "openai-compatible",
    "llm"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "CHANGELOG.md"
  ],
  "engines": {
    "opencode": "^2.0.0"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  }
}

import { Plugin, Model, Provider } from "@opencode/plugin"

/**
 * AIFS /v2/models response shape (OpenAI-compatible with meta_data nesting).
 * The helper fetches ${baseURL}/models with Bearer auth, where baseURL and
 * apiKey come from the provider entry's settings (resolved by the host).
 */
interface AifsModelMeta {
  display_name: string
  model_type: string
  source_type: string
  max_sequence_length: number
  max_output_length: number
  deployment_region: string
  deployment_country: string
  location: string
  input_modalities: string[]
  output_modalities: string[]
  model_lifecycle_stage: string
  license: string
  is_externally_hosted: boolean
  end_of_life_date: string | null
}

interface AifsModel {
  id: string
  meta_data: AifsModelMeta
}

interface AifsResponse {
  data: AifsModel[]
}

/** One row of the model catalog embedded in the public AIFS docs page (SSR
 *  `data-rows` attribute). Only the fields relevant here are declared — the
 *  page carries more. `key` is the join field for AIFS model IDs; prices are
 *  USD per million tokens. A `type` alias, not an `interface`: rows are
 *  persisted inside a `DocsCacheRecord`, and interfaces do not get the
 *  implicit index signature that assignability to the storage's `Schema.Json`
 *  requires. */
type DocsCatalogRow = {
  key: string
  inputPrice: number | null
  outputPrice: number | null
  cachedInputPrice: number | null
  toolCalling: boolean | null
}

/** Snapshot of the docs catalog persisted to plugin storage, so a plugin
 *  load within the TTL of the previous one skips the page fetch entirely.
 *  `rows` are the parsed page rows, not the raw HTML. A `type` alias for the
 *  same `Schema.Json` assignability reason as `DocsCatalogRow`. */
type DocsCacheRecord = {
  fetchedAt: number
  rows: DocsCatalogRow[]
}

/** Plugin options.
 *
 *  `provider_ids` registers models under one or more provider IDs. Use an
 *  array when you maintain multiple AIFS provider entries (e.g. one per
 *  project API key) — the plugin loads once and iterates, instead of being
 *  loaded N times. `providerIDs` is the deprecated legacy alias; when both
 *  are present, `provider_ids` wins.
 *
 *  `reasoning_efforts` maps AIFS model IDs to reasoning-effort values. Every
 *  discovered model with an entry gets one selectable variant per effort
 *  (selected as `provider/model#effort`). Empty-string entries are filtered;
 *  the option never creates models — it only decorates discovered ones.
 *
 *  `verbose` enables diagnostic logging (default off). A `reasoning_efforts`
 *  entry for a model no provider returns may be a typo — but also expected
 *  absence (plan-gated models, per-key model filtering), so it stays quiet
 *  unless the user opts in. The same applies to registered models that join
 *  no docs-catalog row (some docs keys drift from API model IDs).
 *
 *  Credentials (`baseURL`, `apiKey`) are read from each provider entry's
 *  `settings` in opencode.json(c); they are not accepted as plugin options.
 *  The host resolves `{env:VAR}` placeholders before exposing settings, so
 *  values are plain strings by the time the plugin reads them. */
interface AifsPluginOptions {
  provider_ids?: string[]
  /** Deprecated legacy alias for `provider_ids`. */
  providerIDs?: string[]
  reasoning_efforts?: Record<string, string[]>
  /** Docs-catalog cache lifetime in seconds. Valid: finite number >= 0.
   *  `0` = bypass-and-refresh — this launch never serves the cache (a fetch
   *  failure then degrades to no enrichment, not stale data) and still
   *  writes a fresh record back, so it self-heals. It is the only escape
   *  hatch from the stale-on-failure fallback — not equivalent to `1`.
   *  Absent or `null` → default, silent; anything else present-but-invalid
   *  (negative, NaN, string) → default + one error line. Scope: docs
   *  catalog only — the AIFS API is always fetched fresh. */
  cache_ttl_sec?: number
  verbose?: boolean
}

/**
 * Keep only chat-relevant models: LLMs that emit text output.
 * Embeddings, OCR, decision, and image-generation models are skipped —
 * they are not useful for OpenCode agents.
 */
function isChatModel(m: AifsModel): boolean {
  return (
    m.meta_data?.model_type === "LLM" &&
    (m.meta_data.output_modalities ?? []).some((o) => o.toLowerCase() === "text")
  )
}

/** Map one docs-catalog row to a `Model.Info` cost entry (USD per million
 *  tokens — the unit the schema brands). The schema requires every money
 *  field per entry, so a row without published input/output prices yields no
 *  entry at all (unknown price, not free), while missing cache prices fall
 *  back to zero — the same sentinel opencode's own models.dev ingestion uses.
 *  AIFS publishes no cache-write price, so write is always zero. The optional
 *  `tier` struct is omitted — AIFS has no tiered pricing. */
function toCostEntry(row: DocsCatalogRow): Model.Cost | undefined {
  const { input, output } = Model.Cost.fields
  const { read, write } = Model.Cost.fields.cache.fields
  if (row.inputPrice == null || row.outputPrice == null) return undefined
  return Model.Cost.make({
    input: input.make(row.inputPrice),
    output: output.make(row.outputPrice),
    cache: {
      read: row.cachedInputPrice == null ? read.zero : read.make(row.cachedInputPrice),
      write: write.zero,
    },
  })
}

function toModelInfo(
  providerID: Provider.ID,
  m: AifsModel,
  reasoningEfforts: Record<string, string[]>,
  docsRow?: DocsCatalogRow,
): Model.Info {
  const id = Model.ID.make(m.id)
  const base = Model.Info.default(providerID, id)
  const stage = (m.meta_data.model_lifecycle_stage ?? "").toLowerCase()
  const status: Model.Info["status"] = stage === "experimental" ? "beta" : "active"
  // Empty-string entries are ignored; an absent/empty array means no variants.
  // The option only decorates discovered models — it never creates models.
  const efforts = (reasoningEfforts[m.id] ?? []).filter((e) => e !== "")
  const cost = docsRow === undefined ? undefined : toCostEntry(docsRow)

  return {
    ...base,
    name: m.meta_data.display_name || m.id,
    type: "chat",
    status,
    // AIFS /v2/models does not report tool-calling support; the docs catalog
    // does. Only an explicit `false` flips the default (true) — `true`,
    // missing values, and join misses all keep it.
    capabilities: {
      ...base.capabilities,
      ...(docsRow?.toolCalling === false ? { tools: false } : {}),
      input: (m.meta_data.input_modalities ?? []).map((s) => s.toLowerCase()),
      output: (m.meta_data.output_modalities ?? []).map((s) => s.toLowerCase()),
    },
    limit: {
      context: m.meta_data.max_sequence_length ?? base.limit.context,
      output: m.meta_data.max_output_length ?? base.limit.output,
    },
    // base.cost is []; a matched docs row with usable prices adds one entry.
    ...(cost !== undefined ? { cost: [cost] } : {}),
    variants: efforts.map((e) => ({
      id: Model.VariantID.make(e),
      body: { reasoning_effort: e },
    })),
  }
}

/**
 * Config-defined providers are not available during plugin `setup` — the host
 * activates them after all plugins load. Poll the transform editor until the
 * provider entry appears and exposes resolved `baseURL`/`apiKey` in its
 * settings, or until `timeoutMs` elapses. The host resolves `{env:...}`
 * placeholders before exposing settings, so values are plain strings.
 *
 * Returns the resolved credentials, or undefined on timeout.
 */
async function waitForProviderSettings(
  ctx: Plugin.Context,
  providerID: Provider.ID,
  timeoutMs = 10000,
): Promise<{ baseURL: string; apiKey: string } | undefined> {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    let settings: Record<string, unknown> = {}
    await ctx.provider.transform((editor) => {
      const record = editor.get(providerID)
      settings = (record?.provider?.settings ?? {}) as Record<string, unknown>
    })

    const baseURL = typeof settings.baseURL === "string" ? settings.baseURL : undefined
    const apiKey = typeof settings.apiKey === "string" ? settings.apiKey : undefined
    if (baseURL && apiKey) return { baseURL, apiKey }

    await new Promise((r) => setTimeout(r, 100))
  }
  return undefined
}

/** Public AIFS docs page carrying the model catalog as an SSR `data-rows`
 *  attribute. Provider-independent (prices are the same across API keys):
 *  one snapshot per plugin load is shared by every provider, and a fresh
 *  snapshot is persisted to plugin storage (`DOCS_CACHE_KEY`) so plugin loads
 *  within the TTL skip the page fetch entirely. */
const DOCS_CATALOG_URL = "https://docs.llmhub.t-systems.net/models/"

/** Plugin-storage key for the cached docs-catalog record. The host
 *  namespaces it `plugin.<id>.<key>`, so the dev (`aifs-dev`) and published
 *  (`aifs`) plugin instances keep separate caches on the same machine. */
const DOCS_CACHE_KEY = "docs-catalog"

/** Default `cache_ttl_sec` when the option is absent or invalid. */
const DEFAULT_CACHE_TTL_SEC = 7200

/** Build the catalog map from untrusted rows — the same code and the same
 *  `key` guard for both the live fetch and the cache read-back, so cached
 *  rows are never trusted more (or less) than freshly fetched ones. A
 *  non-array input yields an empty map. */
function buildDocsCatalog(rows: unknown): Map<string, DocsCatalogRow> {
  const catalog = new Map<string, DocsCatalogRow>()
  if (!Array.isArray(rows)) return catalog
  for (const row of rows as DocsCatalogRow[]) {
    if (typeof row?.key === "string") catalog.set(row.key, row)
  }
  return catalog
}

/** Fetch the docs catalog from the live page into a map keyed by `key` (the
 *  join field for AIFS model IDs). The API remains the source of truth for
 *  everything it reports; the catalog only fills the gaps (cost,
 *  tool-calling). Never throws: any failure (fetch, HTTP, timeout,
 *  extraction, parse) logs one error and returns an empty map. The empty map
 *  doubles as the caller's failure signal — see `loadDocsCatalog`. */
async function fetchDocsCatalog(timeoutMs = 10000): Promise<Map<string, DocsCatalogRow>> {
  try {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeoutMs)
    try {
      const res = await fetch(DOCS_CATALOG_URL, { signal: controller.signal })
      if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`)
      const html = await res.text()
      // Exactly one data-rows attribute; quotes inside it are numeric
      // entities (&#34;), so [^"]* spans the whole payload.
      const attr = html.match(/data-rows="([^"]*)"/)?.[1]
      if (attr === undefined) throw new Error("no data-rows attribute found")
      const decoded = attr.replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n))).replace(/&amp;/g, "&")
      const rows = JSON.parse(decoded) as unknown
      return buildDocsCatalog(rows)
    } finally {
      clearTimeout(timer)
    }
  } catch (err) {
    console.error(`[opencode-aifs-provider] Docs catalog fetch failed (${DOCS_CATALOG_URL}):`, err)
    return new Map()
  }
}

/** Read the cached docs-catalog record from plugin storage. The stored value
 *  is untrusted `Schema.Json`: shape-checked here before use — a malformed
 *  record is treated as absent. Storage errors never break discovery; any
 *  error logs and yields undefined. */
async function readDocsCacheRecord(ctx: Plugin.Context): Promise<DocsCacheRecord | undefined> {
  try {
    const raw = await ctx.storage.get(DOCS_CACHE_KEY)
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return undefined
    // The cast is required, not convenience: `Array.isArray` does not narrow
    // away effect's `JsonArray` (a `readonly Json[]`), so `raw` is still
    // `JsonArray | JsonObject` here and cannot be destructured directly.
    // Each field is re-checked before use.
    const { fetchedAt, rows } = raw as Record<string, unknown>
    if (typeof fetchedAt !== "number" || !Number.isFinite(fetchedAt)) return undefined
    if (!Array.isArray(rows)) return undefined
    return { fetchedAt, rows: rows as DocsCatalogRow[] }
  } catch (err) {
    console.error(`[opencode-aifs-provider] Docs cache read failed:`, err)
    return undefined
  }
}

/** Resolve the docs catalog for one plugin load:
 *
 *  - fresh record (age < ttlSec) → serve it, skip the page fetch;
 *  - otherwise fetch the page and persist the new record (persist failures
 *    are logged and ignored);
 *  - fetch failure → serve the stale record if one is held — better than an
 *    empty catalog; enrichment fields degrade gracefully by design. This
 *    fallback is skipped entirely when ttlSec is 0, which means "never serve
 *    the cache" including stale data — the only escape hatch from this path,
 *    and NOT equivalent to 1.
 *
 *  Failure is signaled by `fetchDocsCatalog`'s empty map: every failure mode
 *  funnels there, and the only empty non-failure case (a page whose rows
 *  carry no keys) means a dead page, where a stale record still beats
 *  nothing. */
async function loadDocsCatalog(
  ctx: Plugin.Context,
  ttlSec: number,
  verbose: boolean,
): Promise<Map<string, DocsCatalogRow>> {
  let record: DocsCacheRecord | undefined
  if (ttlSec === 0) {
    // Bypass-and-refresh: skip the read, fetch unconditionally, write back —
    // a later load caches again without any config change.
    console.error(`[opencode-aifs-provider] cache_ttl_sec=0: bypassing docs cache for this launch`)
  } else {
    record = await readDocsCacheRecord(ctx)
    if (record !== undefined) {
      const ageSec = (Date.now() - record.fetchedAt) / 1000
      // A backwards clock jump makes the age negative → served "fresh"; the
      // cache just lives slightly longer. Wall clock is the only option for
      // a TTL that spans restarts; accepted.
      if (ageSec < ttlSec) {
        if (verbose) {
          console.error(
            `[opencode-aifs-provider] docs cache hit (age ${Math.round(ageSec)}s, ttl ${ttlSec}s)`,
          )
        }
        return buildDocsCatalog(record.rows)
      }
    }
  }

  const docs = await fetchDocsCatalog()
  if (docs.size > 0) {
    try {
      await ctx.storage.set(DOCS_CACHE_KEY, { fetchedAt: Date.now(), rows: [...docs.values()] })
    } catch (err) {
      console.error(`[opencode-aifs-provider] Docs cache persist failed:`, err)
    }
    return docs
  }

  if (ttlSec !== 0 && record !== undefined) {
    console.error(
      `[opencode-aifs-provider] Docs fetch failed or returned no rows — serving stale docs cache (age ${Math.round((Date.now() - record.fetchedAt) / 1000)}s)`,
    )
    return buildDocsCatalog(record.rows)
  }
  // Reached only when nothing was served: the page failed or carried no
  // usable rows and no stale fallback applied. Unconditional, like the fetch
  // failure line — a silently missing enrichment is an error condition, not
  // an expected-absence diagnostic.
  console.error(`[opencode-aifs-provider] Docs catalog unavailable — no cost/tool-calling enrichment this load`)
  return docs
}

/** Fetch /models for one provider, map to Model.Info, register via transform.
 *  Returns the count of registered models, the model IDs the API returned
 *  (pre-filter, so the caller can detect configured models that no provider
 *  offers), and the registered IDs (post-filter, so the caller can report
 *  docs-catalog join misses) — or undefined on failure (so the caller can
 *  skip the entry in its summary). Errors are logged and isolated: one
 *  provider's failure does not abort the others. */
async function registerForProvider(
  ctx: Plugin.Context,
  providerID: Provider.ID,
  reasoningEfforts: Record<string, string[]>,
  docs: Map<string, DocsCatalogRow>,
): Promise<{ count: number; returnedIDs: Set<string>; registeredIDs: Set<string> } | undefined> {
  const creds = await waitForProviderSettings(ctx, providerID)
  if (!creds) {
    console.error(
      `[opencode-aifs-provider] Provider "${providerID}" not found or missing baseURL/apiKey in its settings within 10s. ` +
        `Set them in the providers entry (e.g. "baseURL": "{env:AIFS_BASE_URL}").`,
    )
    return undefined
  }

  const url = `${creds.baseURL.replace(/\/+$/, "")}/models`

  let res: Response
  try {
    res = await fetch(url, { headers: { Authorization: `Bearer ${creds.apiKey}` } })
  } catch (err) {
    console.error(`[opencode-aifs-provider] Failed to reach ${url} for provider "${providerID}":`, err)
    return undefined
  }
  if (!res.ok) {
    console.error(`[opencode-aifs-provider] ${url} (provider "${providerID}") returned ${res.status} ${res.statusText}`)
    return undefined
  }

  const json = (await res.json()) as AifsResponse
  if (!Array.isArray(json.data)) {
    console.error(`[opencode-aifs-provider] Response from ${url} (provider "${providerID}") missing 'data' array`)
    return undefined
  }

  const returnedIDs = new Set(json.data.map((m) => m.id))
  const chatModels = json.data.filter(isChatModel)
  const models: Model.Info[] = chatModels.map((m) =>
    toModelInfo(providerID, m, reasoningEfforts, docs.get(m.id)),
  )

  await ctx.provider.transform((editor) => {
    editor.models.set(providerID, models)
  })

  return { count: models.length, returnedIDs, registeredIDs: new Set(chatModels.map((m) => m.id)) }
}

export default Plugin.define({
  // Dev identity: distinct from the published plugin's id ("aifs") so the two
  // instances can coexist in the merged config without a registry collision.
  // prepare-pub.mjs rewrites this back to "aifs" in dist/src/index.ts.
  id: "aifs",
  setup(ctx) {
    const opts = (ctx.options ?? {}) as AifsPluginOptions
    const reasoningEfforts = opts.reasoning_efforts ?? {}
    const verbose = opts.verbose ?? false
    const providerIDs = (opts.provider_ids ?? opts.providerIDs ?? ["aifs"]).map((id) => Provider.ID.make(id))

    if (providerIDs.length === 0) {
      console.error("[opencode-aifs-provider] provider_ids is empty; nothing to do.")
      return
    }

    const ttlSec = resolveCacheTtlSec(opts.cache_ttl_sec)

    // Config-defined providers are NOT available during plugin setup — the host
    // activates them after all plugins load. Fire-and-forget the registration;
    // waitForProviderSettings polls the editor until the provider entry appears
    // (up to 10s), so setup returns immediately and the host can finish booting.
    setTimeout(() => { void registerAllProviders(ctx, providerIDs, reasoningEfforts, verbose, ttlSec) }, 0)

    // No cleanup needed; the deferred registration is one-shot.
  },
})

/** Validate `cache_ttl_sec`. Absent or `null` → default, silent (matches the
 *  `??` convention the other options use for absent values). Present but
 *  invalid (negative, NaN, string, object) → default + one error line: the
 *  default keeps the cache ON — the safe direction for what is most likely a
 *  typo ("disable" has the legitimate spelling 0) — and one code path covers
 *  every junk input. Valid: finite number >= 0. */
function resolveCacheTtlSec(raw: unknown): number {
  if (raw === undefined || raw === null) return DEFAULT_CACHE_TTL_SEC
  if (typeof raw === "number" && Number.isFinite(raw) && raw >= 0) return raw
  // JSON.stringify renders Infinity (JSONC "1e999") as "null" — String()
  // keeps numbers honest; JSON.stringify keeps objects/strings readable.
  const shown = typeof raw === "number" ? String(raw) : JSON.stringify(raw)
  console.error(
    `[opencode-aifs-provider] cache_ttl_sec: invalid value ${shown} — using default ${DEFAULT_CACHE_TTL_SEC}s`,
  )
  return DEFAULT_CACHE_TTL_SEC
}

async function registerAllProviders(
  ctx: Plugin.Context,
  providerIDs: Provider.ID[],
  reasoningEfforts: Record<string, string[]>,
  verbose: boolean,
  ttlSec: number,
): Promise<void> {
  // The docs catalog is public and provider-independent, so one snapshot per
  // plugin load is shared by every provider. loadDocsCatalog serves it from
  // cache, fetches fresh, or degrades to stale on failure — the AIFS API
  // stays always-fresh regardless.
  const docs = await loadDocsCatalog(ctx, ttlSec, verbose)
  const summary: { providerID: Provider.ID; count: number }[] = []
  const returnedIDs = new Set<string>()
  const unmatchedIDs = new Set<string>()

  for (const providerID of providerIDs) {
    const result = await registerForProvider(ctx, providerID, reasoningEfforts, docs)
    if (result !== undefined) {
      summary.push({ providerID, count: result.count })
      for (const id of result.returnedIDs) returnedIDs.add(id)
      for (const id of result.registeredIDs) if (!docs.has(id)) unmatchedIDs.add(id)
    }
  }

  const total = summary.reduce((acc, s) => acc + s.count, 0)
  const perProvider = summary.map((s) => `${s.providerID}: ${s.count}`).join(", ")
  console.error(
    `[opencode-aifs-provider] Discovered ${total} chat models across ${summary.length} provider(s) (${perProvider})`,
  )

  // Both diagnostics below may flag expected absence, not errors — configured
  // reasoning_efforts entries the key filters out, and docs keys that drift
  // from API model IDs — so they stay quiet by default. Opt in with the
  // `verbose` option. Skipped when every provider failed, since their
  // per-provider errors already explain why.
  if (!verbose || summary.length === 0) return
  const missing = Object.keys(reasoningEfforts).filter((id) => !returnedIDs.has(id))
  if (missing.length > 0) {
    console.error(
      `[opencode-aifs-provider] reasoning_efforts: configured model ID(s) not returned by any provider: ${missing.join(", ")}`,
    )
  }
  if (unmatchedIDs.size > 0) {
    console.error(
      `[opencode-aifs-provider] docs catalog: registered model ID(s) with no docs row (no cost/tool-calling enrichment): ${[...unmatchedIDs].join(", ")}`,
    )
  }
}
